package cli

import (
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"

	"github.com/madeintandem/tiller/internal/gen"
	"github.com/stretchr/testify/require"
)

// stampOrientation rewrites the checkout's orientation as if generated by a
// binary of the given generation.
func stampOrientation(t *testing.T, root string, generation int) {
	t.Helper()
	current := "orientation generation " + strconv.Itoa(gen.OrientationGeneration())
	stamped := strings.Replace(gen.Orientation(), current, "orientation generation "+strconv.Itoa(generation), 1)
	require.NotEqual(t, gen.Orientation(), stamped, "the fixture must change the stamp")
	require.NoError(t, os.WriteFile(filepath.Join(root, ".tiller", "orientation.md"), []byte(stamped), 0o644))
}

// joinedProject scaffolds a project with a registered, joined contributor, so
// identity and harness wiring exist alongside orientation.
func joinedProject(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	t.Chdir(root)
	for _, args := range [][]string{
		{"init", "--name", "P", "--key", "p", "--kind", "greenfield"},
		{"add", "contributor", "jc", "--name", "JC"},
		{"join", "--as", "jc"},
	} {
		_, stderr, code := execCLI(t, args...)
		require.Equal(t, 0, code, stderr)
	}
	return root
}

// TestInitRerunRefusesNewerOrientation pins bug hunt defect 16 (init rerun
// downgrades orientation). A schema-compatible checkout whose orientation a
// newer binary wrote refuses init's refresh with the same orientation_newer
// contract upgrade uses, and changes nothing: not orientation, identity,
// harness wiring, nor a missing skeleton directory init would otherwise ensure.
func TestInitRerunRefusesNewerOrientation(t *testing.T) {
	root := joinedProject(t)
	stampOrientation(t, root, gen.OrientationGeneration()+1)
	require.NoError(t, os.Remove(filepath.Join(root, ".tiller", "plans")))
	beforeFiles, beforeDirs := snapshotWholeTree(t, root)

	out, stderr, code := execCLI(t, "init", "--name", "P", "--key", "p", "--kind", "greenfield", "--json")
	require.Equal(t, 3, code, out+stderr)
	require.Contains(t, out, `"reason": "orientation_newer"`)

	afterFiles, afterDirs := snapshotWholeTree(t, root)
	require.Equal(t, beforeFiles, afterFiles)
	require.ElementsMatch(t, beforeDirs, afterDirs)
}

// Same- and older-generation reruns still refresh orientation to this binary's.
func TestInitRerunRefreshesSameOrOlderOrientation(t *testing.T) {
	for _, generation := range []int{gen.OrientationGeneration(), gen.OrientationGeneration() - 1} {
		t.Run(strconv.Itoa(generation), func(t *testing.T) {
			root := joinedProject(t)
			if generation != gen.OrientationGeneration() {
				stampOrientation(t, root, generation)
			}
			_, stderr, code := execCLI(t, "init", "--name", "P", "--key", "p", "--kind", "greenfield")
			require.Equal(t, 0, code, stderr)
			got, err := os.ReadFile(filepath.Join(root, ".tiller", "orientation.md"))
			require.NoError(t, err)
			require.Equal(t, gen.Orientation(), string(got))
		})
	}
}

// A fresh init over an orphaned newer orientation (no tiller.yml) refuses
// before writing anything, including the manifest.
func TestFreshInitOverOrphanedNewerOrientationWritesNothing(t *testing.T) {
	root := t.TempDir()
	t.Chdir(root)
	require.NoError(t, os.MkdirAll(filepath.Join(root, ".tiller"), 0o755))
	stampOrientation(t, root, gen.OrientationGeneration()+1)
	beforeFiles, beforeDirs := snapshotWholeTree(t, root)

	out, stderr, code := execCLI(t, "init", "--name", "P", "--key", "p", "--kind", "greenfield", "--json")
	require.Equal(t, 3, code, out+stderr)
	require.Contains(t, out, `"reason": "orientation_newer"`)

	afterFiles, afterDirs := snapshotWholeTree(t, root)
	require.Equal(t, beforeFiles, afterFiles)
	require.ElementsMatch(t, beforeDirs, afterDirs)
}
